 const isAdmin=profile?.role==='admin';const isReception=profile?.role==='reception';const roleNav:ModuleKey[]=roleModules[profile?.role||'']||['home'];const savedModules=Array.isArray(profile?.permissions?.modules)?profile.permissions.modules as ModuleKey[]:null;const visibleNav=nav.filter(n=>roleNav.includes(n[0])&&(isAdmin||!savedModules||savedModules.includes(n[0])));const branch=branches.find(b=>b.id===branchId);const org=profile?.organization_id;const currentModule=nav.find(n=>n[0]===moduleKey)?.[2]||'';
 const loadModule=useCallback(async()=>{if(!supabase||!profile||!org||!branchId)return;setBusy(true);setError('');let table='patients';if(moduleKey==='appointments')table='appointments';if(moduleKey==='operations')table='operations';if(moduleKey==='staff')table='staff_schedules';if(moduleKey==='users')table='profiles';if(moduleKey==='finance')table='financial_transactions';if(moduleKey==='reports')table='financial_transactions';if(moduleKey==='home'){setBusy(false);return;}if(moduleKey==='users'&&!isAdmin){setError('إدارة المستخدمين متاحة للـ Admin فقط.');setRows([]);setBusy(false);return;}let q=supabase.from(table).select('*').limit(1000);if(table!=='profiles'&&branchId!=='__all__')q=q.eq('branch_id',branchId);else if(table==='profiles')q=q.eq('active',true);if(moduleKey==='staff'&&branchId!=='__all__')q=q.eq('branch_id',branchId);if(moduleKey==='appointments')q=q.order('scheduled_at',{ascending:true});else if(moduleKey==='operations')q=q.order('scheduled_at',{ascending:false});else if(moduleKey==='finance'||moduleKey==='reports')q=q.order('paid_at',{ascending:false});else if(moduleKey==='staff')q=q.order('weekday',{ascending:true});else q=q.order('created_at',{ascending:false});const r=await q;if(r.error){setError(r.error.message);setRows([]);}else if(moduleKey==='users'&&isAdmin){const ids=(r.data||[]).map((u:Row)=>u.id);const memberships=ids.length?await supabase.from('user_branch_access').select('user_id,branch_id').in('user_id',ids):{data:[]};setRows((r.data||[]).map((u:Row)=>{const branchIds=(memberships.data||[]).filter((m:Row)=>m.user_id===u.id).map((m:Row)=>m.branch_id);const selected=branchIds.length?branchIds:(u.branch_id?[u.branch_id]:[]);return {...u,branch_ids:selected,branch_names:selected.map((id:string)=>branches.find((b:Row)=>b.id===id)?.name).filter(Boolean).join(' + ')};}));}else setRows(r.data||[]);setBusy(false);},[moduleKey,profile,org,branchId,branches]);
 useEffect(()=>{let cancelled=false;async function init(){if(!supabase){router.replace('/login');return;}const {data:{user}}=await supabase.auth.getUser();if(!user){router.replace('/login');return;}const p=await supabase.from('profiles').select('*').eq('id',user.id).maybeSingle();if(p.error||!p.data){setError('الملف الشخصي غير مهيأ. يحتاج Admin إنشاء Profile وربطه بالمؤسسة والفرع.');return;}if(cancelled)return;setProfile(p.data);const b=await supabase.from('branches').select('*').eq('organization_id',p.data.organization_id);if(cancelled)return;setBranches(b.data||[]);let permittedBranches:string[]=(b.data||[]).map((x:Row)=>x.id);if(p.data.role!=='admin'){const memberships=await supabase.from('user_branch_access').select('branch_id').eq('user_id',user.id);permittedBranches=(memberships.data||[]).map((x:Row)=>x.branch_id);if(!permittedBranches.includes(p.data.branch_id)&&p.data.branch_id)permittedBranches.push(p.data.branch_id);setUserBranchIds(permittedBranches);}else setUserBranchIds((b.data||[]).map((x:Row)=>x.id));const firstBranch=p.data.role==='admin'?'__all__':p.data.branch_id||permittedBranches[0]||'';setBranchId(firstBranch);const pt=await supabase.from('patients').select('id,full_name,patient_number,age,created_at').in('branch_id',permittedBranches.length?permittedBranches:[firstBranch]).limit(1000).order('created_at',{ascending:false});setPatients(pt.data||[]);const ap=await supabase.from('appointments').select('patient_id').in('branch_id',permittedBranches.length?permittedBranches:[firstBranch]);const eligible=new Set((ap.data||[]).map((x:Row)=>x.patient_id));setAppointmentPatients((pt.data||[]).filter((x:Row)=>eligible.has(x.id)));const st=await supabase.from('profiles').select('id,full_name,role,branch_id,active').eq('organization_id',p.data.organization_id).eq('active',true);const stAccess=st.data?.length?await supabase.from('user_branch_access').select('user_id,branch_id').in('user_id',st.data.map((x:Row)=>x.id)):{data:[]};setStaff((st.data||[]).map((u:Row)=>({...u,branch_ids:(stAccess.data||[]).filter((x:Row)=>x.user_id===u.id).map((x:Row)=>x.branch_id)})));}init();return()=>{cancelled=true}},[router]);
 useEffect(()=>{loadModule()},[loadModule]); useEffect(()=>{if(!supabase||!profile||!org)return;const refreshLive=async()=>{await loadModule();const freshProfile=await supabase!.from('profiles').select('*').eq('id',profile.id).maybeSingle();if(freshProfile.data&&(freshProfile.data.role!==profile.role||freshProfile.data.active!==profile.active||freshProfile.data.branch_id!==profile.branch_id||JSON.stringify(freshProfile.data.permissions)!==JSON.stringify(profile.permissions)))setProfile(freshProfile.data);else if(freshProfile.error)setError('تعذر تحديث صلاحيات الحساب.');if(freshProfile.data?.active===false){await supabase!.auth.signOut();router.replace('/login');return;}const targetBranches=branchId==='__all__'?branches.map((b:Row)=>b.id):[branchId];if(targetBranches.length){const [pt,ap]=await Promise.all([supabase!.from('patients').select('id,full_name,patient_number,age,created_at').in('branch_id',targetBranches).limit(1000).order('created_at',{ascending:false}),supabase!.from('appointments').select('patient_id').in('branch_id',targetBranches)]);setPatients(pt.data||[]);const eligible=new Set((ap.data||[]).map((x:Row)=>x.patient_id));setAppointmentPatients((pt.data||[]).filter((x:Row)=>eligible.has(x.id)));const st=await supabase!.from('profiles').select('id,full_name,role,branch_id,active').eq('organization_id',org).eq('active',true);const stAccess=st.data?.length?await supabase!.from('user_branch_access').select('user_id,branch_id').in('user_id',st.data.map((x:Row)=>x.id)):{data:[]};setStaff((st.data||[]).map((u:Row)=>({...u,branch_ids:(stAccess.data||[]).filter((x:Row)=>x.user_id===u.id).map((x:Row)=>x.branch_id)})));if(profile.role!=='admin'){const memberships=await supabase!.from('user_branch_access').select('branch_id').eq('user_id',profile.id);setUserBranchIds((memberships.data||[]).map((x:Row)=>x.branch_id));}if(moduleKey==='home'){const c=await Promise.all(['patients','appointments','operations'].map(t=>supabase!.from(t).select('*',{count:'exact',head:true}).in('branch_id',targetBranches)));setCounts({patients:c[0].count||0,appointments:c[1].count||0,operations:c[2].count||0});}}};const channel=supabase.channel(`clinic-live-${profile.id}`).on('postgres_changes',{event:'*',schema:'public',table:'patients'},refreshLive).on('postgres_changes',{event:'*',schema:'public',table:'appointments'},refreshLive).on('postgres_changes',{event:'*',schema:'public',table:'operations'},refreshLive).on('postgres_changes',{event:'*',schema:'public',table:'financial_transactions'},refreshLive).on('postgres_changes',{event:'*',schema:'public',table:'profiles'},refreshLive).on('postgres_changes',{event:'*',schema:'public',table:'user_branch_access'},refreshLive).on('postgres_changes',{event:'*',schema:'public',table:'staff_schedules'},refreshLive).on('postgres_changes',{event:'*',schema:'public',table:'operation_labs'},refreshLive).on('postgres_changes',{event:'*',schema:'public',table:'patient_images'},refreshLive).on('postgres_changes',{event:'*',schema:'public',table:'patient_private_details'},refreshLive).on('postgres_changes',{event:'*',schema:'public',table:'appointment_private_details'},refreshLive).on('postgres_changes',{event:'*',schema:'public',table:'visits'},refreshLive).on('postgres_changes',{event:'*',schema:'public',table:'operation_team_assignments'},refreshLive).on('postgres_changes',{event:'*',schema:'public',table:'operation_private_details'},refreshLive).subscribe((status)=>{setLiveConnected(status==='SUBSCRIBED');});return()=>{setLiveConnected(false);supabase.removeChannel(channel);};},[profile,org,branchId,moduleKey,branches,loadModule,router]);
 useEffect(()=>{if(!supabase||!branchId)return;async function loadBranchPatients(){const targetBranches=branchId==='__all__'?branches.map((b:Row)=>b.id):[branchId];const pt=await supabase!.from('patients').select('id,full_name,patient_number,age,created_at').in('branch_id',targetBranches).limit(1000).order('created_at',{ascending:false});setPatients(pt.data||[]);const ap=await supabase!.from('appointments').select('patient_id').in('branch_id',targetBranches);const eligible=new Set((ap.data||[]).map((x:Row)=>x.patient_id));setAppointmentPatients((pt.data||[]).filter((x:Row)=>eligible.has(x.id)));}loadBranchPatients();},[branchId,branches]);
